#include "ksStatePanelRefreshTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::StatePanelRefreshTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned seed=0;seed<65536;++seed){T task;unsigned clocks=0,reads=0;std::vector<unsigned> children;std::array<unsigned,12> input{};for(unsigned i=0;i<12;++i)input[i]=uint8_t(seed*17+i*19);input[2]=seed&255;input[3]=seed>>8;auto read=[&](T::Read r){check(unsigned(r)==reads++,"Panel lateobservationorder");return input[unsigned(r)];};while(!task.complete()){if(task.awaitingChild()){children.push_back(unsigned(task.child())<<16|task.key()<<8|(task.child()==T::Child::Indicator?task.value():0));check(task.resumeChild(),"Panel childresume");continue;}auto c=task.nextClocks(),n=reads;check(!task.advanceBefore(c-1,read)&&n==reads,"Panel earlyobservation");check(task.advanceBefore(c,read)==c,"Panel admission");clocks+=c;}std::vector<unsigned> expected;for(unsigned i=0;i<9;++i)expected.push_back((38+i)<<8);expected.push_back(0x10000|1<<8);expected.push_back(0x10000|14<<8);constexpr unsigned keys[]{2,6,11,12,13,17,16,3,10,20,21};for(unsigned i=0;i<11;++i){unsigned value=input[i+1];if(i==1)value=value>>2&1;if(i==2)value=value>>4&1;expected.push_back(0x20000|keys[i]<<8|value);}check(children==expected&&reads==12&&clocks==964,"Panel commandbatch/latevalues/order/clocks");check(!task.resumeChild(),"Panel lifecycle");++cases;}std::cout<<"PASS: "<<cases<<" complete panelrefresh jobs,22typedcommands/12independentlateobservations/allLFO-filterbytepairs/exactorder/deadlines+clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
